  }
  const tw = 8*0.95;
  const act=aS/tw, inh=iS/tw, act2=aS2/tw, inh2=iS2/tw;
  const bg = (Math.sin(dx*0.035+dy*0.022+t*0.7) + Math.sin(dx*0.028-dy*0.038+t*1.05) + Math.sin(dx*0.015+dy*0.045-t*0.5))/3;
  const micro = (Math.sin(dx*0.12+t*1.8)*Math.sin(dy*0.11-t*1.4) + Math.sin((dx+dy)*0.08+t*2.2)*0.7)*0.35;
