  const cross = Math.tanh((r1*0.6 + r2*0.4 + Math.sin(r1*r2*3.14)*0.3)*2.2);
  const cell = Math.tanh((Math.sin(dx*0.13)*Math.sin(dy*0.13) + Math.sin((dx+dy)*0.09+t)*0.5 + Math.sin(dx*0.07-dy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const membrane = Math.abs(Math.sin(dx*0.14)*Math.sin(dy*0.14))<0.08 ? 0.15 : 0;
